      if (!target) throw new TRPCError5({ code: "NOT_FOUND", message: "\u0627\u06CC\u0646 \u06A9\u0627\u0631\u0628\u0631 \u062F\u0631 \u067E\u0627\u06CC\u06AF\u0627\u0647 \u062F\u0627\u062F\u0647\u0654 Kronos Guard \u067E\u06CC\u062F\u0627 \u0646\u0634\u062F\u061B \u0627\u0628\u062A\u062F\u0627 \u0631\u0628\u0627\u062A \u0631\u0627 \u062F\u0631 \u06AF\u0641\u062A\u200C\u0648\u06AF\u0648\u06CC \u062E\u0635\u0648\u0635\u06CC Start \u06A9\u0646\u062F." });
      if (!target.startedBotAt) throw new TRPCError5({ code: "PRECONDITION_FAILED", message: "\u06A9\u0627\u0631\u0628\u0631 \u0628\u0627\u06CC\u062F \u0627\u0628\u062A\u062F\u0627 \u0631\u0628\u0627\u062A Kronos Guard \u0631\u0627 \u062F\u0631 \u06AF\u0641\u062A\u200C\u0648\u06AF\u0648\u06CC \u062E\u0635\u0648\u0635\u06CC Start \u06A9\u0646\u062F." });
      return { telegramUserId: target.telegramUserId, username: target.username ?? null, firstName: target.firstName ?? null, readyForInvoice: true };
