        if (!["channel", "supergroup", "group"].includes(channel.type)) throw new Error("\u0645\u0642\u0635\u062F \u0648\u0627\u0631\u062F\u0634\u062F\u0647 \u06A9\u0627\u0646\u0627\u0644 \u06CC\u0627 \u06AF\u0631\u0648\u0647 \u062A\u0644\u06AF\u0631\u0627\u0645 \u0646\u06CC\u0633\u062A");
        const botMembership = await bot2.telegram.getChatMember(channel.id, botIdentity.id);
