import express from "express";
import fs3 from "fs";
import { nanoid as nanoid3 } from "nanoid";
import path3 from "path";
async function setupVite(app, server) {
  const [{ createServer: createViteServer }, { default: viteConfig }] = await Promise.all([
    import("vite"),
    Promise.resolve().then(() => (init_vite_config(), vite_config_exports))
  ]);
  const serverOptions = {
    middlewareMode: true,
    hmr: { server },
    allowedHosts: true
  };
  const vite = await createViteServer({
    ...viteConfig,
    configFile: false,
    server: serverOptions,
    appType: "custom"
  });
  app.use(vite.middlewares);
  app.use("*", async (req, res, next) => {
    const url = req.originalUrl;
    try {
      const clientTemplate = path3.resolve(
        import.meta.dirname,
        "../..",
        "client",
        "index.html"
      );
      let template = await fs3.promises.readFile(clientTemplate, "utf-8");
      template = template.replace(
        `src="/src/main.tsx"`,
        `src="/src/main.tsx?v=${nanoid3()}"`
      );
      const page = await vite.transformIndexHtml(url, template);
      res.status(200).set({ "Content-Type": "text/html" }).end(page);
    } catch (e) {
      vite.ssrFixStacktrace(e);
      next(e);
    }
  });
}
function resolveStaticDirectory(moduleDirectory = import.meta.dirname, exists = fs3.existsSync) {
  const candidates = [
    path3.resolve(moduleDirectory, "public"),
    path3.resolve(moduleDirectory, "../..", "dist", "public")
  ];
  return candidates.find(exists) ?? candidates[0];
}
function serveStatic(app) {
  const distPath = resolveStaticDirectory();
  if (!fs3.existsSync(distPath)) {
    console.error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`
    );
  }
  app.use(express.static(distPath));
  app.use("*", (_req, res) => {
    res.sendFile(path3.resolve(distPath, "index.html"), (error) => {
      if (!error) return;
      console.error(`[static] failed to serve ${distPath}/index.html`, error);
      if (!res.headersSent) {
        res.status(500).json({ error: "static-entrypoint-unavailable" });
      }
    });
  });
}

